// Geminiが返したテキスト（JSON文字列）を取り出す。ノード構成で入る場所が違うため複数候補を見る。
let raw = $json.text ?? $json.content ?? $json.response ?? $json.output ?? $json.data ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
// ```json ... ``` のコードフェンスが付く場合があるので除去
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let p = {};
try {
  p = JSON.parse(raw);
} catch (e) {
  p = { _parse_error: String(e), _raw: raw };
}
return [{ json: {
  "会社名": p.company || '',
  "氏名": p.name || '',
  "役職": p.title || '',
  "電話": p.phone || '',
  "携帯": p.mobile || '',
  "メール": p.email || '',
  "住所": p.address || ''
} }];
